/**
 * The app's icon in the launcher (`LauncherIcon`, `mobile/shared/android`). Android cannot paint a
 * launcher icon: each app has a launcher entry per palette (an `<activity-alias>` of MainActivity
 * whose meta-data names the palette, generated by tools/icons/build_android_drawables.mjs), each
 * with the mark in that palette's primary, and exactly one is turned on.
 */
import type { TurboModule } from 'react-native';
import { TurboModuleRegistry } from 'react-native';

export interface Spec extends TurboModule {
  /** The palette whose entry is on; '' when this build has none, or not exactly one is on. */
  current(): string;
  /**
   * Turns that palette's entry on, then every other off (the app is not stopped, but the task the
   * launcher opened through an entry turned off is closed); false when this build has none for it, or
   * not now: another activity (a picker, the camera, a permission's dialog) waits in that task.
   */
  choose(palette: string): boolean;
  /** The activity the entries open (MainActivity's class name), for what must name it; '' when this build has no entries. */
  mainActivity(): string;
}

export default TurboModuleRegistry.get<Spec>('LauncherIcon');
